{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리의 원인에 맞는 개선 조치를 선택할 수 있는지 확인한다. 신고 목록 조회에 인덱스를 추가하고 조인을 정리하기로 한 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "운영 화면의 신고 목록 조회 쿼리를 개선했다.",
          "action": "실행 계획에서 확인한 내용과 인덱스 추가·조인 정리를 선택한 근거를 연결해 설명한다.",
          "result": "조회 시간이 0.4초로 줄어든 결과가 자신의 판단 근거와 어떤 관련이 있는지 답변에 포함된 범위에서 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 개선 조치로 선택한 근거",
          "판단을 뒷받침한 실행 계획의 내용과 조회 조건",
          "확인한 병목과 선택한 조치 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리를 개선하셨을 때, 인덱스 추가와 조인 정리를 선택한 근거는 무엇이었나요?",
      "answerTip": "말씀할 내용을 짧게 정리한 뒤 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획이나 조회 조건에서 확인한 구체적인 문제를 인덱스 추가·조인 정리의 선택 근거로 제시한다.",
            "선택한 조치가 확인한 병목을 줄일 수 있다고 판단한 이유를 쿼리의 데이터 접근이나 조인 작업과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가·조인 정리를 선택한 근거를 제시하지만 실행 계획이나 조회 조건에 대한 설명이 일반적이다.",
            "선택한 조치와 병목 사이의 관련성을 설명하지만 어떤 불필요한 작업을 줄이는지에 대한 연결이 일부 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "수행한 조치나 개선된 시간만 반복하고 해당 조치를 선택한 근거는 제시하지 못한다.",
            "인덱스는 빠르다는 일반론이나 사용 도구 설명에 머물러 신고 목록 조회의 병목과 연결하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 확인한 장애 원인을 같은 장애의 재발을 막는 조치로 연결할 수 있는지 확인한다. 오류 수정과 별도로 스케줄러 점검을 배포 체크리스트에 추가한 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 간다는 문의가 들어왔고, 로그에서 스케줄러가 서버 두 대에서 동시에 실행되는 것을 확인했다.",
          "task": "잠금 키를 두는 방식으로 오류를 고쳤고, 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "확인한 중복 실행 원인과 연결해 스케줄러 항목을 배포 체크리스트에 넣기로 한 근거를 설명한다.",
          "result": "체크리스트의 스케줄러 점검이 같은 오류의 재발 위험을 줄일 수 있다고 본 이유를 설명하며, 실제 재발 여부는 단정하지 않는다."
        },
        "expectedEvidence": [
          "스케줄러 항목을 배포 체크리스트에 추가하기로 한 판단 근거",
          "서버 두 대에서 스케줄러가 동시에 실행됐다는 로그 확인 내용",
          "확인한 중복 실행 위험과 배포 시 스케줄러 점검의 연결"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 고치셨을 때, 스케줄러 항목을 배포 체크리스트에 넣기로 판단한 근거는 무엇이었나요?",
      "answerTip": "말씀할 내용을 짧게 정리한 뒤 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 서버 두 대의 스케줄러 중복 실행을 체크리스트 추가의 구체적인 근거로 제시한다.",
            "오류를 고치는 조치와 별도로 배포 시 스케줄러를 점검하는 것이 같은 중복 실행 위험을 줄이는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 중복 발송의 재발을 막으려는 판단을 제시하지만 확인한 중복 실행 원인과의 연결은 일반적이다.",
            "배포 체크리스트에 스케줄러 점검을 넣은 취지는 설명하지만 같은 오류를 막는 데 필요한 점검인 이유가 일부 빠져 있다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키로 고쳤거나 체크리스트에 항목을 넣었다는 사실만 반복하고 추가한 판단 근거를 제시하지 못한다.",
            "체크리스트가 중요하다는 일반론에 머물거나 확인한 스케줄러 중복 실행과 무관한 근거를 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "흩어진 요청을 구현할 요구사항으로 구체화할 수 있는지 확인한다. 개발 담당 팀원과 범위를 조정한 경험에서 요구사항에 담을 범위를 정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "플랜업스쿨 서비스 기획 과정에서 동네 세탁소 예약 서비스 기획 프로젝트를 진행했다.",
          "task": "기획 담당으로 세탁소 5곳 인터뷰를 통해 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 확인한 요청과 구현할 범위를 연결해, 요구사항에 담을 범위를 정한 근거를 설명한다.",
          "result": "설명한 근거가 포함하거나 제외할 요구사항을 구분하는 데 어떤 의미가 있었는지 설명한다."
        },
        "expectedEvidence": [
          "요구사항에 담을 범위를 정한 구체적인 근거",
          "그 근거를 뒷받침하는 인터뷰 내용이나 범위 조정 당시의 제약"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨을 때, 요구사항에 담을 범위를 정한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요구사항에 담을 범위를 정한 근거를 프로젝트의 구체적인 요청이나 제약에 연결해 설명한다.",
            "제시한 근거로 요구사항의 포함·제외 또는 우선순위를 구분할 수 있어 범위 판단이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항의 범위를 정한 근거를 제시하지만 사용자 필요나 구현 여건에 관한 일반적인 설명에 머문다.",
            "근거와 범위 판단의 연결은 드러나지만 무엇을 포함하거나 제외할지 구분하는 설명이 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항에 담을 범위를 정한 근거를 제시하지 않고 문서를 작성했다는 사실만 반복한다.",
            "범위 판단과 무관한 도구 사용이나 팀 활동만 설명해 요구사항을 구분한 판단을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름과 예외 상황을 구현 가능한 화면 흐름으로 설계할 수 있는지 확인한다. 예약·취소·알림 화면설계 경험에서 예외 상황의 화면 흐름을 정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획 프로젝트에서 예약·취소·알림 흐름과 예외 상황을 담은 화면설계서 28장을 작성했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서를 작성했다.",
          "action": "화면설계서에 담은 예외 상황을 짚어, 해당 상황의 화면 흐름을 정한 근거를 설명한다.",
          "result": "설명한 근거가 예외 상황에서 사용자가 보게 될 화면이나 이어갈 동작을 명확히 하는 데 어떤 의미가 있는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름을 정한 구체적인 근거",
          "그 근거와 연결되는 화면 상태나 사용자 동작의 예"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름을 화면설계서로 작성하셨을 때, 예외 상황의 화면 흐름을 정한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 흐름을 정한 근거를 실제 설계한 예외 상황에 연결해 구체적으로 설명한다.",
            "제시한 근거가 해당 상황의 화면 상태나 사용자 동작과 맞물려 화면 흐름을 정한 판단이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 화면 흐름을 정한 근거를 제시하지만 사용자 편의나 혼란 방지 같은 일반적인 설명에 머문다.",
            "근거와 화면 흐름의 연결은 드러나지만 해당 상황의 화면 상태나 사용자 동작과의 연결이 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황의 화면 흐름을 정한 근거를 제시하지 않고 화면설계서를 작성했다는 사실만 반복한다.",
            "화면 흐름 판단과 무관한 도구 기능이나 시각적 취향만 설명해 예외 상황을 설계한 판단을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 확인할 수 있는지 평가한다. 평소와 다른 진통제 용량을 보고 투약을 중단한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약·처치를 맡았으며, 해당 처방을 보고 투약을 멈추고 담당의에게 확인했다.",
          "action": "처방 용량의 차이를 투약 전에 확인해야 할 문제로 판단한 근거를 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실이 투약 중단 판단의 근거와 어떤 관련이 있는지 설명한다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 판단한 근거",
          "처방 용량이 평소 용량의 두 배였다는 비교 정보",
          "확인되지 않은 용량으로 투약할 때 생길 수 있는 위험에 대한 판단"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈추고 담당의에게 확인하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 처방 용량의 구체적인 차이를 투약 중단의 근거로 설명한다.",
            "용량 차이의 적절성을 확인하지 않은 채 투약해서는 안 된다는 판단을 환자 안전과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 확인이 필요했다고 답하지만 비교 정보가 구체적이지 않다.",
            "잘못된 투약을 피하려고 멈췄다는 취지는 드러나지만 해당 처방에서 우려한 점은 일반적으로 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단 근거를 제시하지 않고 입력 오류였다는 결과만 반복한다.",
            "처방의 의심스러운 점을 확인해야 한다는 판단 없이 처방대로 투약하면 된다는 일반론으로 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보가 근무 교대 때 빠지지 않도록 인수인계에 반영할 수 있는지 평가한다. 낙상 고위험 환자의 인수인계 체크리스트를 바꾸자고 제안한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
